1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	const countDistinctTypes = (cards: Card[]): number =>
11	  new Set(cards.map((card) => card.monster)).size;
12	
13	const BASE_SCORE = 1;
14	const MINIMUM_BONUS = 1;
15	const POINTS_PER_EXTRA_TYPE = 2;
16	const TYPES_BEFORE_BONUS = 3;
17	
18	// Every Sphinx in an army scores the same: the score depends only on how
19	// varied the rest of the army is, not on which Sphinx card we are looking at.
20	const scorePerSphinx = (army: Card[]): number => {
21	  const otherTypes = countDistinctTypes(army.filter((card) => !isSphinx(card)));
22	  const extraTypes = otherTypes - TYPES_BEFORE_BONUS;
23	  const bonus =
24	    extraTypes > 0 ? POINTS_PER_EXTRA_TYPE * extraTypes : MINIMUM_BONUS;
25	  return BASE_SCORE + bonus;
26	};
27	
28	const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;
29	
30	export const scoreArmy = (army: Card[]): number =>
31	  countSphinxes(army) * scorePerSphinx(army);
32

